local({
  typed <- lookup_values(trimws(iconv(Q4_10_TEXT, "UTF-8", "ASCII", sub = "")), lookup_ethnicity_other)
  coded <- lookup_values(
    as.character(Q4),
    lookup_ethnicity,
    dataset_id = spec$dataset_id,
    target_variable = "ethnicity"
  )
  coalesce(if_else(Q4 == 10 | typed %in% "Mixed", typed, coded), "Unknown")
})
